arguments.command:
python -c "import selenide_followup as s; import numpy as np; import pandas as pd; f,t=s.build(); base=[x for x in s.SMALL if x not in ['Ga_q','Ga_cn']]; f['Zn_projGa']=f.Zn_T0_norm*f.ZnGa0cos; f['Mg_projGa']=f.Mg_T0_norm*f.MgGa0cos; configs={'base':base,'coval':base+['coval0norm'],'proj':base+['Zn_projGa'],'both':base+['Zn_projGa','Mg_projGa'],'coval_both':base+['coval0norm','Zn_projGa','Mg_projGa']}; y=f.y.iloc[:33].to_numpy(); g=f.formula.iloc[:33].to_numpy(); out=f.iloc[38:][['id','formula']].reset_index(drop=True); results={};
for name,cols in configs.items():
 s.SMALL=cols
 for kind in ['ridge_robust','ridge','ridge_log']:
  r=s.evaluate(f,t,np.arange(33),kind); key=name+'_'+kind; out[key]=r[1]; results[key]=r; print(s.summary(key,y,r[0],g),flush=True)
print(out.round(4).to_string(index=False)); print('ENSMETRIC',s.summary('base_coval_robust',y,(results['base_ridge_robust'][0]+results['coval_ridge_robust'][0])/2,g))"

python -c "import pandas as pd; import numpy as np; from pymatgen.core import Structure; from pymatgen.symmetry.analyzer import SpacegroupAnalyzer; p=pd.read_csv('nlo_pool.csv');
for cid in ['c022','c052']:
 r=p.loc[p.candidate_id==cid].iloc[0]; s=Structure.from_str(r.poscar,fmt='poscar'); print(cid,r.formula,'V/atom',s.volume/len(s),'SG',SpacegroupAnalyzer(s,symprec=.03).get_space_group_symbol()); anion='P' if cid=='c022' else 'S'
 for e in ['W'] if cid=='c022' else ['Zn','Ga']:
  aa=[]
  for site in s:
   if site.specie.symbol!=e: continue
   ns=sorted([n for n in s.get_neighbors(site,5.5) if n.specie.symbol==anion],key=lambda n:n.nn_distance); ns=[n for n in ns if n.nn_distance<=ns[0].nn_distance*1.22]; aa.append((len(ns),np.mean([n.nn_distance for n in ns]),min(n.nn_distance for n in ns),max(n.nn_distance for n in ns)))
  print(e,'coordination, mean/min/max bond length',aa)
print('INPUT_RECORDS',len(pd.read_csv('nlo_shg_train.csv')),len(p),'unique IDs',p.candidate_id.nunique(),'missing inputs',p.isna().sum().to_dict())"

